"use client";
/* Crowd, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Crowd(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("core"); }, []);
  return React.createElement("piix-crowd", piixAttrs(props));
}

export default Crowd;
